-- The employer feedback form for internships, and the audience a feedback template is for (intern or employer).
-- An intervention can now have one template per audience.

alter table public.feedback_template add column if not exists audience text not null default 'intern'
  check (audience in ('intern', 'employer'));
alter table public.feedback_template drop constraint feedback_template_pkey;
alter table public.feedback_template add primary key (intervention_id, audience);

-- Fields the employer form uses (the keys are the question ids).

select i.id, 'employer', 'Employer feedback', $json$[{"id": "student_name", "label": "Student Name", "type": "text", "required": false}, {"id": "student_email", "label": "Student email address", "type": "email", "required": true}, {"id": "supervisor_name", "label": "Supervisor Name", "type": "text", "required": false}, {"id": "organisation_name", "label": "Organization Name", "type": "text", "required": false}, {"id": "asks_questions", "label": "Asks effective questions to clarify expectations and understand context", "type": "single", "required": false, "options": ["Never", "Rarely", "Sometimes", "Often", "Consistently"]}, {"id": "communication", "label": "Communicates professionally in writing and conversation", "type": "single", "required": false, "options": ["Never", "Rarely", "Sometimes", "Often", "Consistently"]}, {"id": "deadlines", "label": "Meets deadlines and delivers work on time", "type": "single", "required": false, "options": ["Never", "Rarely", "Sometimes", "Often", "Consistently"]}, {"id": "teamwork", "label": "Works effectively in teams and maintains positive relationships", "type": "single", "required": false, "options": ["Never", "Rarely", "Sometimes", "Often", "Consistently"]}, {"id": "health_understanding", "label": "Demonstrates understanding of health systems/context and real-world health challenges", "type": "single", "required": false, "options": ["Not at all", "Somewhat", "Moderately", "Very much", "Extremely"]}, {"id": "applies_skills", "label": "Applies their skills effectively to health-specific problems and contexts", "type": "single", "required": false, "options": ["Not at all", "Somewhat", "Moderately", "Very much", "Extremely"]}, {"id": "comparative_performance", "label": "This student's performance relative to other, non-ALU students is significantly better.", "type": "single", "required": false, "options": ["Strongly Disagree", "Disagree", "Neutral", "Agree", "Strongly Agree"]}, {"id": "overall_satisfaction", "label": "Overall, how satisfied are you with the quality and performance of ALU intern(s)?", "type": "single", "required": false, "options": ["Very Dissatisfied", "Dissatisfied", "Neutral", "Satisfied", "Very Satisfied"]}, {"id": "performance_rating", "label": "On a scale of 0–10, how would you rate this student's overall performance? (0 = Poor, 10 = Excellent)", "type": "scale10", "required": false}, {"id": "rating_reason", "label": "What is the primary reason for your rating? (Please include specific examples if possible)", "type": "long", "required": false}, {"id": "strengths", "label": "What were the student's greatest strengths?", "type": "long", "required": false}, {"id": "development_areas", "label": "What are their most noticeable areas for development?", "type": "long", "required": false}, {"id": "career_advice", "label": "What advice would you give this student for their career in health?", "type": "long", "required": false}, {"id": "employer_recommend", "label": "On a scale of 0–10, how likely are you to recommend ALU students to other organizations/professionals? (0 = Not at all likely, 10 = Extremely likely)", "type": "scale10", "required": false}, {"id": "hire_likelihood", "label": "If a suitable position were available, how likely would your organization hire another ALU graduate/intern?", "type": "single", "required": false, "options": ["Very Unlikely", "Unlikely", "Unsure", "Likely", "Very Likely"]}, {"id": "hire_drivers", "label": "What would make you MORE likely to hire ALU graduates? (Select top 2)", "type": "multi", "required": false, "options": ["Stronger technical skills in their field", "Deeper understanding of health systems", "More independence and initiative", "Better soft skills (communication, teamwork, leadership)", "Other, please specify"]}, {"id": "open_to_call", "label": "Are you open to a brief call to discuss your feedback or share insights on this student?", "type": "single", "required": false, "options": ["Yes, I'm open to a call", "No, thank you"]}]$json$::jsonb
from public.interventions i where i.name = 'Internships' and i.pillar = 'HEMP';
